class View:
    def __init__(self):
        self.rows = []
        self.notes = {}
        self.loading = False
        self.error = None
        self.seq = 0
        self.current_request_id = None

    def begin(self, query):
        self.seq += 1
        self.current_request_id = self.seq
        self.loading = True
        self.error = None
        return self.seq

    def finish(self, request_id, rows):
        if request_id != self.current_request_id:
            return False

        self.rows = copy.deepcopy(rows)
        self.loading = False
        return True
